import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import '../core/theme/forge_theme.dart';
import '../features/app_generation/presentation/screens/conversation_flow_screen.dart';
import '../json_ui/renderer/forge_renderer.dart';

/// FORGE v0.2 P5対応(指示書19章「Generated by Forge」)。
///
/// 生成されたアプリを開いた際、邪魔にならない小さな`Generated by Forge`
/// 表示を、Runtime文書の内部(偽Widgetとして)ではなく、Host側の薄い
/// Shellとして重ねる。アプリ本体の操作は一切妨げない
/// (`IgnorePointer`は使わず、ラベル自体が画面下部の狭い帯に収まるのみ)。
///
/// FORGE-PRODUCT-VISION-002(2026-08-11)対応: `onDocumentUpdated`を
/// 渡した呼び出し元でのみ、「ここを変える」ボタンが現れる(Held→
/// Forming→Heldの入口、design doc C章)。`StatelessWidget`から
/// `StatefulWidget`へ変更したのは、更新後のDocumentをこのWidget自身が
/// 保持し、`ForgeDocumentView`を新しい内容で再描画するため
/// (呼び出し元は「保存してほしい」という通知だけを`onDocumentUpdated`
/// 経由で受け取り、実際の永続化方法は呼び出し元が決める——My Apps
/// 画面・履歴画面等、保存先を持たない画面は単にこの引数を渡さなければ
/// よく、影響を受けない)。
class GeneratedAppHostShell extends ConsumerStatefulWidget {
  final Map<String, dynamic> forgeDocument;
  final VoidCallback? onBack;

  /// FORGE-AI-QUALITY-001(2026-08-11)新設(ローカル永続化対応)。
  /// 画面ID→前回保存された実行時State。呼び出し元(`AppLibraryRepository`
  /// 経由でローカルストレージから読み込む My Apps・履歴・ホーム画面の
  /// 各画面)が渡す。生成直後でまだ保存されていないプレビュー
  /// (`generation_flow_screen.dart`)からは渡されず、その場合は
  /// 常に文書の初期値のまま(既存の挙動を保つ)。
  final Map<String, Map<String, dynamic>>? initialRuntimeState;

  /// FORGE-AI-QUALITY-001(2026-08-11)新設。渡した場合のみ、実際に
  /// アプリの状態変化がローカルストレージへ保存される(呼び出し元が
  /// 保存先を持たない場合は渡さないだけでよい、既定`null`で無効)。
  final void Function(String screenId, Map<String, dynamic> stateJson)? onScreenStateChanged;

  /// FORGE-PRODUCT-VISION-002(2026-08-11)新設。非nullの場合のみ、
  /// 「ここを変える」ボタンを表示する。`ConversationFlowScreen`が
  /// `/converse`経由でUPDATE(TD40)に成功すると、更新済みのDocumentを
  /// 持ってこのコールバックが呼ばれる(呼び出し元は永続化するかどうかを
  /// 自由に決めてよい)。
  final void Function(Map<String, dynamic> updatedDocument)? onDocumentUpdated;

  /// 会話に使うAI Provider(Home画面のトグルと同じ値、既定`null`=Backend既定)。
  final String? provider;

  const GeneratedAppHostShell({
    super.key,
    required this.forgeDocument,
    this.onBack,
    this.initialRuntimeState,
    this.onScreenStateChanged,
    this.onDocumentUpdated,
    this.provider,
  });

  @override
  ConsumerState<GeneratedAppHostShell> createState() => _GeneratedAppHostShellState();
}

class _GeneratedAppHostShellState extends ConsumerState<GeneratedAppHostShell> {
  late Map<String, dynamic> _document = widget.forgeDocument;

  Future<void> _openEditConversation() async {
    final updated = await Navigator.of(context).push<Map<String, dynamic>>(
      MaterialPageRoute<Map<String, dynamic>>(
        builder: (_) => ConversationFlowScreen(
          provider: widget.provider, currentDocument: _document,
        ),
      ),
    );
    if (updated == null || !mounted) return;
    setState(() => _document = updated);
    widget.onDocumentUpdated?.call(updated);
  }

  @override
  Widget build(BuildContext context) {
    return Stack(
      children: [
        Positioned.fill(child: ForgeDocumentView(
          rawJson: _document,
          initialRuntimeState: widget.initialRuntimeState,
          onScreenStateChanged: widget.onScreenStateChanged,
        )),
        if (widget.onBack != null)
          Positioned(
            top: MediaQuery.of(context).padding.top + 8,
            left: 8,
            child: _RoundIconButton(icon: Icons.arrow_back_rounded, onPressed: widget.onBack!),
          ),
        if (widget.onDocumentUpdated != null)
          Positioned(
            top: MediaQuery.of(context).padding.top + 8,
            right: 8,
            child: _RoundIconButton(icon: Icons.chat_bubble_outline_rounded, onPressed: _openEditConversation),
          ),
        Positioned(
          bottom: 10,
          left: 0,
          right: 0,
          child: IgnorePointer(
            child: Center(
              child: Container(
                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                decoration: BoxDecoration(
                  color: ForgeTheme.ink.withValues(alpha: 0.55),
                  borderRadius: BorderRadius.circular(999),
                ),
                child: const Text(
                  'Generated by Forge',
                  style: TextStyle(fontSize: 10, color: Colors.white, fontWeight: FontWeight.w500),
                ),
              ),
            ),
          ),
        ),
      ],
    );
  }
}

class _RoundIconButton extends StatelessWidget {
  final IconData icon;
  final VoidCallback onPressed;
  const _RoundIconButton({required this.icon, required this.onPressed});

  @override
  Widget build(BuildContext context) {
    return Material(
      color: ForgeTheme.surface.withValues(alpha: 0.92),
      shape: const CircleBorder(),
      elevation: 1,
      child: IconButton(
        icon: Icon(icon, color: ForgeTheme.ink),
        tooltip: '戻る',
        onPressed: onPressed,
      ),
    );
  }
}
